-- Native prompt-layer contracts; no model/provider request or live settings.
local json=dofile('lua/vendor/json.lua');local memory=dofile('lua/core/memory.lua');memory.setup()
local agent=dofile('lua/core/agent.lua');local tools=dofile('lua/core/tools.lua');local parts=dofile('lua/core/prompt_sections.lua')
host.http=function()error('network forbidden')end
local checks=0;local function check(v,why)assert(v,why);checks=checks+1 end
local sid=memory.start_session('','layers',{user_id='master'});local ctx={session_id=sid,user_id='master',role='master'}
local schemas=tools.envelope('master',ctx);local names={};for _,s in ipairs(schemas)do names[s['function'].name]=true end
check(#schemas==14 and names.read_many and names.web_search and names.web_read,'read_many is native main-loop bootstrap')
check(not names.capabilities and not names.tool_result,'only catalog/evidence helpers remain deferred')
local one=agent.system_sections('master','PROJECT_KEEP','a"&<.md',schemas,'progressive')
local two=agent.system_sections('master','OTHER_PROJECT','b.md',schemas,'progressive',{orchestration_enabled=true})
check(one.generic==two.generic,'generic layer independent of workflow/project')
check(one.stack==two.stack,'stack contract independent of project/workflow')
check(one.project~=two.project and one.workflow~=two.workflow,'only intended layers change')
local patch=parts.diff(one,two);check(patch.project and patch.workflow and not patch.generic and not patch.stack,'section diff locates injection rather than rewriting generic')
check(parts.diff(one,one)==nil,'identical prompt has no section patch')
check(parts.diff({removed='x'},{}).removed==false,'deletion explicit')
check(parts.section('optional','')==nil,'empty injection omitted')
check(not pcall(parts.section,'bad><tag','x'),'invalid section refuses')
check(not pcall(parts.section,'good','x',{['bad"']='v'}),'invalid attribute refuses')
check(parts.section('good','x',{source='a"&<'})=='<good source="a&quot;&amp;&lt;">\nx\n</good>','attribute escaping')
local prompt=agent.system_prompt('master','PROJECT_KEEP','a"&<.md',schemas,'progressive')
local previous=0;for _,tag in ipairs({'generic','stack','workflow','project','session'})do local at=assert(prompt:find('<'..tag,1,true));check(at>previous,'stable layer order '..tag);previous=at end
for _,tag in ipairs({'identity','style','language','memory','tools','skills','guidelines','safety','environment','role','workdir','orchestration'})do check(prompt:find('<'..tag,1,true),'visible section '..tag)end
check(prompt:find('mode="off"',1,true) and two.workflow:find('mode="on"',1,true),'explicit active workflow mode')
check(prompt:find('PROJECT_KEEP',1,true) and prompt:find('source="a&quot;&amp;&lt;.md"',1,true),'project bytes retained, source escaped')
check(not prompt:find('Available tools:',1,true),'no progressive duplicate schema index')
check(prompt:find('request them together with read_many',1,true),'direct batching cue retained')
check(prompt:find('Before answering anything about the user',1,true),'memory-on-demand protocol retained')
check(prompt:find('Never weaken checks or blindly replay effects',1,true),'shared skill safety retained')
check(prompt:find('automated status report, not a human',1,true),'Sentinel notice never authority')
check(not one.generic:find('Sentinel',1,true) and one.stack:find('Sentinel',1,true),'stack-only notice contract separated')
local guest=agent.system_prompt('guest','GUEST_PROJECT','AGENTS.guest.md',tools.all('guest'),'full')
check(not guest:find('<workflow',1,true) and not guest:find('AGENTS.orchestrator',1,true),'guest never inherits operator workflow')
check(guest:find('GUEST_PROJECT',1,true),'guest-specific project retained')
local full=agent.system_prompt('master','PROJECT','AGENTS.md',tools.all('master'),'full')
check(full:find('Available tools:',1,true) and full:find('<available_skills>',1,true),'full mode keeps declarations/metadata contract within named layers')
local child=agent.subagent_system_prompt({role='master',subagent={allowed={read=true}}},tools.all_for({read=true},'master'))
check(child:find('bounded child task',1,true) and not child:find('PROJECT_KEEP',1,true),'mandatory child boundary remains separate')
memory.remember('SECRET_FACT_NOT_AUTOMATIC','fixture')
local bot=agent.new(sid,function()end,'master','master','');local messages=bot:build_context()
check(not json.encode(messages):find('SECRET_FACT_NOT_AUTOMATIC',1,true),'no memory facts auto-injected')
check(not messages[1].content:find('onSessionStart_injection',1,true),'no new session hook or empty injection')
bot.resume_notice='RECOVERY_KEEP';messages=bot:build_context()
check(messages[2].content:find('<onSessionStart_injection source="resume_notice">',1,true) and messages[2].content:find('RECOVERY_KEEP',1,true),'existing recovery notice sourced and visible')
check(messages[1].content==prompt or messages[1].content:find('<generic>',1,true),'native builder selects layered operator prompt')
assert(host.write_file(assert(host.getenv('WA_LAYER_CAPTURE')),json.encode({ok=true,checks=checks,system=messages[1].content,sections=agent.system_sections('master',assert(host.read_file('AGENTS.md')),'AGENTS.md',schemas,'progressive'),schemas=schemas,system_bytes=#messages[1].content,schema_bytes=#json.encode(schemas),provider_calls=0})))
print('prompt layers ok ('..checks..' checks, 0 skipped)')
